/* Last Shift 0.7: all controls and descriptions are inside the game viewport. */
(()=>{
 'use strict';
 const C=ShiftCore,R=ShiftRooms,D=ShiftMobileData,$=id=>document.getElementById(id);
 let roomCamera=null,cameraState=null,sceneArt=null;
 const t=(ru,en)=>GameLocale.lang==='en'?en:ru;
 let state=C.createState(),location='luch',orderActive=false,discovered=[],journalTab='items',modal=false,zoom=false,sound=false,lastTime=performance.now(),toastTimer,revealTimer;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const score=n=>GameLocale.formatScore(n);
 function cargoSprite(id){const extra=D.extraIds.indexOf(id),n=extra>=0?extra:R.PLACEMENTS[id].atlas,cols=extra>=0?4:5,rows=extra>=0?3:2,src=extra>=0?D.cargoExtra:D.cargoOld;return `<span class="cargo-sprite" aria-hidden="true" style="background-image:url('${src}');--sprite-aspect:${extra>=0?.75:.6};--sheet-size:${cols*100}% ${rows*100}%;--sprite-pos:${n%cols/(cols-1)*100}% ${Math.floor(n/cols)/(rows-1)*100}%"></span>`;}
 function crate(){nav('crate');}
 function inspectCargo(id){const it=C.item(state,id);show(esc(it.name),`<p>${esc(it.description)}</p><div class="facts">${it.facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div>`,[{label:t('Закрыть','Close'),run:close}],t('Уже в ящике','Already in the crate'));}
 const final=()=>['epilogue','ended'].includes(state.phase);
 const running=()=>state.phase==='playing'&&orderActive&&!modal&&!['luch','journal','crate'].includes(location)&&!document.hidden;
 function toast(t){clearTimeout(toastTimer);$('toast').textContent=t;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3000);}
 function close(){modal=false;$('overlay').hidden=true;$('screen').inert=false;document.querySelector('.hud').inert=false;document.querySelector('.bottom-hud').inert=false;lastTime=performance.now();}
 function show(title,body,actions,kicker='ЛУЧ на связи'){modal=true;$('toast').classList.remove('visible');$('dialog-content').innerHTML=`<p class="dialog-kicker">${esc(kicker)}</p><h2 id="dialog-title">${title}</h2>${body}<div class="dialog-buttons">${actions.map((a,i)=>`<button class="btn ${a.secondary?'secondary':''}" data-modal="${i}" ${a.disabled?'disabled':''}>${a.label}</button>`).join('')}</div>`;actions.forEach((a,i)=>$('dialog-content').querySelector(`[data-modal="${i}"]`).addEventListener('click',a.run));$('overlay').hidden=false;$('screen').inert=true;document.querySelector('.hud').inert=true;document.querySelector('.bottom-hud').inert=true;$('dialog-content').querySelector('button:not(:disabled)')?.focus();}
 function nav(next){if(modal)return;if(!['hub','luch','journal','crate',...Object.keys(R.ROOMS)].includes(next))return;if(next!==location){roomCamera?.destroy();roomCamera=null;cameraState=null;}location=next;zoom=false;state.history.push({event:'visit',screen:next});render();}
 function bind(id,fn){$(id)?.addEventListener('click',fn);}
 function render(){
  sceneArt?.destroy();sceneArt=null;
  if(roomCamera){cameraState=roomCamera.getState();roomCamera.destroy();roomCamera=null;}
  const o=C.currentOrder(state);$('home').hidden=location==='hub';$('journal-icon').classList.toggle('current',location==='journal');$('rating').textContent=score(C.rating(state));$('brief').textContent=final()?'Последнее решение: забрать память ЛУЧа?':orderActive?o.text:'ЛУЧ ждёт. Получи новое задание.';$('carry').textContent=state.carry?C.item(state,state.carry).name:'В руках ничего';$('carry').disabled=!state.carry;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('current',b.dataset.nav===location));
  $('screen').className='screen';$('screen').innerHTML='';
  if(location==='hub'){
   $('screen-bg').src=D.hub;$('screen').innerHTML=`<h1 class="screen-title">Шлюз</h1>${Object.entries(R.ROOMS).map(([id,r])=>`<button class="hub-door door-${id}" data-room="${id}"><span class="door-lettering">${r.name}</span></button>`).join('')}<button id="hub-luch" class="hub-luch" aria-label="Терминал ЛУЧа">ЛУЧ</button>${final()?'<button id="send" class="hub-send final-send" aria-label="В капсулу"></button>':''}<div class="cargo-items">${state.saved.map((id,i)=>`<span class="crate-item" style="--cargo-index:${i};left:${20.5+i*3.2}%;top:${60.7-(i%2)*.3}%">${cargoSprite(id)}</span>`).join('')}</div><button id="crate" class="crate-hit" aria-label="Ящик с грузом" title="Ящик с грузом"></button>`;document.querySelectorAll('[data-room]').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.room)));bind('hub-luch',()=>nav('luch'));bind('send',openGate);bind('crate',crate);
  }else if(location==='crate'){
   $('screen-bg').src=D.crate;$('screen').classList.add('crate-screen');
   $('screen').innerHTML=`<h1 class="screen-title">${t('Внутри ящика','Inside the crate')}</h1><div class="crate-cargo">${state.saved.map((id,i)=>`<button class="cargo-object" data-cargo="${id}" aria-label="Осмотреть: ${esc(C.item(state,id).name)}" style="--cargo-index:${i};left:${17+i*16}%;top:${35+(i%2)*2}%">${cargoSprite(id)}</button>`).join('')}</div>${state.saved.length?'':`<p class="empty-crate-note">${t('Пока пусто','Empty for now')}</p>`}<div class="crate-panel"><h2>${t('Груз: ','Cargo: ')}${state.saved.length}</h2><p>${state.carry?esc(C.item(state,state.carry).name):t('В руках ничего. Принеси вещь из отсека.','Empty hands. Bring an item from a room.')}</p><div class="panel-actions">${final()?`<button id="crate-depart" class="btn">${t('Отправиться в капсулу','Board the capsule')}</button>`:`<button id="crate-put" class="btn" ${!state.carry||!orderActive?'disabled':''}>${t('Положить вещь','Put the item inside')}</button>`}<button id="crate-back" class="btn secondary">${t('Вернуться в шлюз','Back to airlock')}</button></div></div>`;
   document.querySelectorAll('[data-cargo]').forEach(b=>b.addEventListener('click',()=>inspectCargo(b.dataset.cargo)));bind('crate-put',openGate);bind('crate-depart',openGate);bind('crate-back',()=>nav('hub'));
  }else if(location==='luch'){
   $('screen-bg').src=D.luch;const title=final()?'Ещё один пассажир':o.title;
   $('screen').innerHTML=`<h1 class="screen-title">ЛУЧ</h1><div class="luch-panel"><h2>${esc(title)}</h2><p>${final()?'«Осталось отключить ненужное оборудование. Меня. Но можете сначала закончить уборку».':esc(o.intro)}</p><p class="order-text">${final()?'В техническом отделе доступен съёмный модуль памяти. Забери его к шлюзу, если хочешь улететь вместе.':esc(o.text)}</p><div class="panel-actions">${final()?'<button id="go-hub" class="btn">Вернуться в шлюз</button>':orderActive?'<button id="go-hub" class="btn">Выполнить задание</button><button id="hint" class="btn secondary">Уточнить</button>':'<button id="take-order" class="btn">Взять задание</button>'}</div><p class="dialog-kicker">Здесь часы остановлены. Подсказки без штрафа.</p></div>`;
   bind('take-order',()=>{orderActive=true;state.history.push({event:'assignment',order:state.orderIndex});toast('Задание принято. Выбери отсек в шлюзе.');nav('hub');});bind('go-hub',()=>nav('hub'));bind('open-journal',()=>nav('journal'));bind('hint',()=>show('Небольшое уточнение',`<p>${esc(C.hint(state))}</p><p>Верность команд не изменилась.</p>`,[{label:'Понятно',run:close}]));
  }else if(location==='journal'){
   $('screen-bg').src=D.luch;const entries=journalTab==='items'?discovered.map(id=>{const it=C.item(state,id);return `<article class="journal-entry"><h3>${esc(it.name)}</h3><small>${R.ROOMS[R.PLACEMENTS[id].room].name}${it.shipped?' · в ящике':''}</small><p>${esc(it.description)}</p><div class="facts">${it.facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div></article>`;}).join('')||'<p>Пока записей нет. Осматривай вещи в отсеках: описание попадёт сюда.</p>':C.ORDERS.map((ord,i)=>{const result=state.results.find(r=>r.order===i),known=result||i===state.orderIndex&&orderActive;return known?`<article class="journal-entry"><h3>${esc(ord.title)}</h3><p>${esc(ord.text)}</p><small>${result?`${result.points}/100 · ${result.item?esc(C.item(state,result.item).name):'Не завершено'}`:'Текущее задание'}</small></article>`:'';}).join('')||'<p>Полученные задания появятся здесь.</p>';
   $('screen').innerHTML=`<h1 class="screen-title">Журнал</h1><div class="journal-panel"><div class="journal-tabs"><button id="tab-items" class="${journalTab==='items'?'selected':''}">Вещи ${discovered.length}/22</button><button id="tab-orders" class="${journalTab==='orders'?'selected':''}">Задания</button></div>${entries}</div>`;bind('tab-items',()=>{journalTab='items';render();});bind('tab-orders',()=>{journalTab='orders';render();});
  }else{
   const room=R.ROOMS[location],available=R.visible(state,location),ids=new Set(available.map(i=>i.id));$('screen-bg').src=room.image;$('screen').classList.add('room-screen');
   const patches=state.items.filter(i=>R.PLACEMENTS[i.id].room===location&&!ids.has(i.id)).map(it=>{const [l,t,w,h]=R.patchBox(it.id);return `<div class="clean-zone" style="left:${l}%;top:${t}%;width:${w}%;height:${h}%"><img alt="" src="${room.clean}" style="width:${10000/w}%;height:${10000/h}%;left:${-100*l/w}%;top:${-100*t/h}%"></div>`;}).join('');
   const buttons=available.map(it=>{const [l,t,w,h]=R.PLACEMENTS[it.id].box;return `<button class="native-item" aria-label="Осмотреть: ${esc(it.name)}" data-item="${it.id}" style="left:${l}%;top:${t}%;width:${w}%;height:${h}%"></button>`;}).join('');
   $('screen').innerHTML=`<h1 class="screen-title">${room.name}</h1><div class="camera-view" id="camera-view"><div id="scene" class="room-scene"><img src="${room.image}" alt="${room.name}, вид от первого лица">${patches}${buttons}</div></div><div class="room-tools"><div class="camera-zoom"><button data-camera-zoom="out" id="zoom-out" aria-label="${t('Отдалить','Zoom out')}">−</button><button data-camera-zoom="in" id="zoom-in" aria-label="${t('Приблизить','Zoom in')}">+</button></div><button id="search-help">Помочь с поиском</button></div><p class="room-note">${t('Проведи по комнате · + и − меняют масштаб','Drag to look around · + and − adjust zoom')}</p>`;
   roomCamera=RoomCamera.attach($('camera-view'),$('scene'),cameraState||{});roomCamera.set(roomCamera.getZoom());bind('zoom-out',()=>roomCamera.set(roomCamera.getZoom()-.08));bind('zoom-in',()=>roomCamera.set(roomCamera.getZoom()+.08));
   document.querySelectorAll('[data-item]').forEach(b=>b.addEventListener('click',()=>inspect(C.item(state,b.dataset.item))));bind('search-help',()=>{clearTimeout(revealTimer);$('scene').classList.add('reveal');state.history.push({event:'search-help',room:location});revealTimer=setTimeout(()=>$('scene')?.classList.remove('reveal'),4500);toast('Вещи отмечены на несколько секунд. Штрафа нет.');});
  }
  if(['hub','crate','luch','journal'].includes(location))sceneArt=SceneArt.attach($('game'),$('screen-bg'),$('screen'),location==='journal'?'luch':location,D);
 }
 function inspect(it){if(!discovered.includes(it.id)){discovered.push(it.id);state.history.push({event:'inspect',item:it.id});}show(esc(it.name),`<p>${esc(it.description)}</p><div class="facts">${it.facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div><p class="dialog-kicker">Записано в журнал. Время остановлено.</p>`,[{label:'Закрыть',secondary:true,run:()=>{close();render();}},...(state.carry===it.id?[{label:'Вернуть на место',run:()=>{R.returnHome(state);close();render();}}]:[{label:state.carry?'Руки заняты':!orderActive&&!final()?'Сначала получи задание':'Взять с собой',disabled:!!state.carry||!orderActive&&!final(),run:()=>{if(C.pickup(state,it.id)){state.history.push({event:'pickup',item:it.id});close();render();toast('Вещь в руках. Вернись в шлюз.');}}}])],'Осмотр');}
 function openGate(){if(final()){const rescue=state.carry==='memory';show(rescue?'Место для двоих':'Отправиться одному?',`<p>${rescue?'«По инструкции здесь должен быть только один пассажир».':'ЛУЧ останется на станции. Можно вернуться за его памятью в технический отдел.'}</p><p>Этот выбор не меняет рейтинг.</p>`,[{label:'Ещё побуду',secondary:true,run:close},{label:rescue?'Забрать ЛУЧа и улететь':'Улететь одному',run:()=>{C.finish(state);close();ending();}}]);return;}if(!orderActive){toast('Сначала получи задание у ЛУЧа.');return;}if(!state.carry){toast('Принеси вещь из отсека.');return;}const it=C.item(state,state.carry);show('Сложить в ящик?',`<p><b>${esc(it.name)}</b></p><p>${esc(C.currentOrder(state).text)}</p>`,[{label:'Ещё подумаю',secondary:true,run:close},{label:'Положить',run:submit}],'Грузовой шлюз');}
 function submit(){close();const r=C.submit(state);render();if(r.type==='wrong'){show('Не совсем по инструкции',`<p>${esc(r.text)}</p><p>Вещь вернулась в свой отсек. За эту попытку −10 баллов. Можно исправиться.</p><p>Проверь запись о ней в журнале.</p>`,[{label:'Исправлюсь',run:close}]);}else if(r.type==='accepted'){orderActive=false;show('Команда выполнена',`<p>${esc(r.text)}</p><p><b>${r.points}/100 за поручение.</b></p>`,[{label:r.finished?'Последний разговор':'К ЛУЧу за следующим',run:()=>{close();location='luch';render();}}]);}}
 function ending(){show(state.rescued?'Последняя смена. Вместе.':'Курс домой',`<div class="score-result">${score(C.rating(state))}</div><p>${state.rescued?'Робот подвигается. В капсуле нашлось место для двоих.':'«Хорошей дороги, маленький». Голос ЛУЧа становится тише.'}</p><table class="results">${state.results.map(r=>`<tr><td>${esc(C.ORDERS[r.order].title)}<span class="result-item">${r.item?esc(C.item(state,r.item).name):'Не завершено'}</span></td><td>${r.points}/100</td></tr>`).join('')}</table>`,[{label:'Журнал смены JSON',secondary:true,run:download},{label:'Ещё одна смена',run:restart}],'Верность команд');}
 function download(){const log={game:'Последняя смена',version:'0.7',rating:C.rating(state),orders:state.results,discovered,events:state.history,rescued:state.rescued};const url=URL.createObjectURL(new Blob([JSON.stringify(log,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='last-shift-mobile-playtest.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function restart(){close();state=C.createState();location='luch';orderActive=false;discovered=[];zoom=false;render();intro();}
 function intro(){show('Последняя смена','<p>Все люди эвакуированы. Остались ты и ЛУЧ.</p><p>Получай задания у ЛУЧа, переходи в отсеки через шлюз и осматривай вещи. За один раз можно нести одну.</p><p>22 похожих предмета. Пять минут поиска. Осмотр, журнал и разговоры останавливают часы.</p><p>Комната занимает весь экран. Проведи по ней для осмотра, кнопки + и − меняют масштаб. Описания сохраняются в журнал.</p>',[{label:'К ЛУЧу',run:()=>{C.start(state);close();render();}}],'Тёплая история на станции «Вереск»');}
 function pause(){if(modal||state.phase!=='playing')return;show('Небольшой перерыв','<p>Время остановлено. Вещи остаются на своих местах.</p>',[{label:'Продолжить',run:close},{label:'Начать заново',secondary:true,run:restart}]);}
 bind('pause',pause);bind('carry',()=>{if(state.carry)inspect(C.item(state,state.carry));});bind('brief',()=>{const o=C.currentOrder(state);show(final()?'Ещё один пассажир':orderActive?o.title:'ЛУЧ ждёт',`<p>${final()?'Спаси память ЛУЧа из технического отдела или отправляйся один.':orderActive?esc(o.text):'Зайди к ЛУЧу и возьми задание.'}</p>`,[{label:'Закрыть',run:close},{label:'К ЛУЧу',secondary:true,run:()=>{close();nav('luch');}}]);});bind('rating',()=>show('Верность команд','<p>За поручение — 100 баллов. Каждая подтверждённая ошибочная отправка отнимает 10, минимум 0. Незавершённое поручение — 0.</p><p>Все подходящие трактовки равноценны. Итог — среднее четырёх поручений. Подсказки, поиск и финальный выбор баллы не отнимают.</p>',[{label:'Понятно',run:close}]));bind('help',()=>show('Как играть','<p>ЛУЧ выдаёт задания. Шлюз ведёт в четыре отсека и отправляет груз. Журнал хранит описания осмотренных вещей и задания.</p><p>Нажми на предмет, осмотри, возьми и вернись в шлюз. Вещь в руках можно осмотреть или вернуть кнопкой внизу.</p><p>Проведи по комнате, чтобы оглядеться. Кнопки + и − немного меняют масштаб. Нажми на ящик в шлюзе, чтобы посмотреть груз и положить вещь. «Помочь с поиском» временно обводит предметы без штрафа.</p>',[{label:'Понятно',run:close}]));document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.nav)));
 bind('journal-icon',()=>nav('journal'));bind('home',()=>nav('hub'));
 window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('keydown',e=>{if(e.code==='Escape'){if(modal&&state.phase==='playing')close();else pause();}});
 setInterval(()=>{const now=performance.now(),dt=Math.min(1,(now-lastTime)/1000);lastTime=now;if(running()&&C.tick(state,dt)){orderActive=false;if(state.carry)R.returnHome(state);location='luch';render();show('Время смены вышло','<p>Незавершённые поручения получили 0. Капсула ждёт. Можно спасти ЛУЧа.</p>',[{label:'Последний разговор',run:close}]);}const t=Math.ceil(state.remaining);$('timer').textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;$('timer').classList.toggle('urgent',t<60);},100);
 render();intro();
})();
